const items = $input.all();
const validUsers = items
  .map(i => i.json)
  .filter(u => u && u.sheetId && String(u.sheetId).trim() !== '');

if (validUsers.length === 0) {
  throw new Error('No registered users with valid sheetId found in Users sheet.');
}

return validUsers.map(u => ({ json: u }));

let currentUser = null;
try {
  currentUser = $('Loop Over Users').item.json;
} catch (e) {}

if (!currentUser || !currentUser.sheetId) {
  try {
    const loopItems = $('Loop Over Users').all();
    if (loopItems && loopItems.length > 0) currentUser = loopItems[0].json;
  } catch (e) {}
}

if (!currentUser || !currentUser.sheetId) {
  try {
    const allUsers = $('Filter Valid Users').all().map(i => i.json);
    const loopContext = $('Loop Over Users').context;
    const runIdx = (loopContext && loopContext.currentRunIndex) || 0;
    currentUser = allUsers[runIdx] || allUsers[0];
  } catch (e) {}
}

currentUser = currentUser || { firstName: 'User', sheetId: '', chatId: '' };

const rawRows = $('Read User Transactions').all().map(i => i.json);

const txs = rawRows.filter(t => t && Object.keys(t).length > 0 && t.amount !== undefined && t.amount !== '' && String(t.type || '').toLowerCase() !== 'deleted');

if (txs.length === 0) {
  return [{
    json: {
      hasTransactions: false,
      sheetId: currentUser.sheetId,
      chatId: currentUser.chatId,
      firstName: currentUser.firstName || 'User',
      txCount: 0,
      insightsText: '👋 Hey ' + (currentUser.firstName || 'there') + '! Your financial dashboard is active. Start logging your daily expenses or income on Telegram, and I will generate your personalized spending analysis and habit tips here!'
    }
  }];
}

let totalSpent = 0;
let totalIncome = 0;
let categories = {};
let vendors = {};
let maxExpense = { amount: 0, vendor: 'None', category: 'None' };
let weekendTx = 0;
let weekdayTx = 0;
let smallTxCount = 0;

txs.forEach(t => {
  const cleanAmt = parseFloat(String(t.amount).replace(/[^0-9.]/g, '')) || 0;
  if (cleanAmt <= 0) return;
  const isIncome = String(t.type || '').toLowerCase() === 'income' || String(t.type || '').toLowerCase() === 'credit';
  const cat = String(t.category || 'Other').trim();
  const vendor = String(t.vendor || t.description || 'Unknown').trim();

  if (isIncome) {
    totalIncome += cleanAmt;
  } else {
    totalSpent += cleanAmt;
    categories[cat] = (categories[cat] || 0) + cleanAmt;
    vendors[vendor] = (vendors[vendor] || 0) + cleanAmt;
    if (cleanAmt > maxExpense.amount) {
      maxExpense = { amount: cleanAmt, vendor, category: cat };
    }
    if (cleanAmt < 50) {
      smallTxCount++;
    }
  }

  if (t.date) {
    const d = new Date(t.date);
    if (!isNaN(d.getTime())) {
      const day = d.getDay();
      if (day === 0 || day === 6) weekendTx++;
      else weekdayTx++;
    }
  }
});

const sortedCats = Object.entries(categories).sort((a,b) => b[1] - a[1]);
const sortedVendors = Object.entries(vendors).sort((a,b) => b[1] - a[1]);

const topCatsFormatted = sortedCats.slice(0, 4).map(([c, amt]) => {
  const pct = totalSpent > 0 ? ((amt / totalSpent) * 100).toFixed(1) : '0';
  return c + ': ₹' + amt.toLocaleString('en-IN') + ' (' + pct + '%)';
});

const topVendorsFormatted = sortedVendors.slice(0, 4).map(([v, amt]) => {
  return v + ': ₹' + amt.toLocaleString('en-IN');
});

const netBalance = totalIncome - totalSpent;
const savingsRate = totalIncome > 0 ? (((totalIncome - totalSpent) / totalIncome) * 100).toFixed(1) : 0;

const userPromptText = 'Financial Summary for ' + (currentUser.firstName || 'User') + ':\n' +
'- Total Transactions: ' + txs.length + '\n' +
'- Total Income: ₹' + totalIncome.toLocaleString('en-IN') + '\n' +
'- Total Spent: ₹' + totalSpent.toLocaleString('en-IN') + '\n' +
'- Net Surplus / Savings: ₹' + netBalance.toLocaleString('en-IN') + ' (' + savingsRate + '% savings rate)\n' +
'- Largest Single Spend: ₹' + maxExpense.amount.toLocaleString('en-IN') + ' on ' + maxExpense.vendor + ' (' + maxExpense.category + ')\n' +
'- Top Spending Categories:\n  ' + (topCatsFormatted.join('\n  ') || 'None') + '\n' +
'- Top Vendors / Recipients:\n  ' + (topVendorsFormatted.join('\n  ') || 'None') + '\n' +
'- Transaction Rhythm: ' + weekdayTx + ' weekday txs vs ' + weekendTx + ' weekend txs\n' +
'- Micro-transactions (<₹50): ' + smallTxCount + ' purchases\n\n' +
'Analyze these exact spending figures and provide 3 to 4 actionable, grounded bullet points for ' + (currentUser.firstName || 'the user') + '.';

return [{
  json: {
    hasTransactions: true,
    sheetId: currentUser.sheetId,
    chatId: currentUser.chatId,
    firstName: currentUser.firstName || 'User',
    txCount: txs.length,
    totalSpent,
    totalIncome,
    netBalance,
    userPromptText
  }
}];

