const item = $input.first()?.json || {};
const prep = $('Prepare Analytics for User').all()[0]?.json || {};

let content = '';

if (item.choices && item.choices.length > 0 && item.choices[0].message) {
  content = item.choices[0].message.content || '';
} else if (item.insightsText) {
  content = item.insightsText;
} else {
  content = typeof item === 'string' ? item : JSON.stringify(item);
}

// Clean reasoning / think tags if local LLM includes them
content = content.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

if (!content || content.length < 10) {
  content = '• Healthy Tracking: Successfully monitored ' + (prep.txCount || 0) + ' transactions. Total spend is ₹' + (prep.totalSpent || 0).toLocaleString('en-IN') + ' against income of ₹' + (prep.totalIncome || 0).toLocaleString('en-IN') + '.';
}

return [{
  json: {
    sheetId: prep.sheetId,
    chatId: prep.chatId,
    firstName: prep.firstName,
    generatedAt: new Date().toISOString(),
    insights: content,
    basedOnTxCount: prep.txCount || 0
  }
}];
